function isValid(s) {
  const stack = [];
  const pairs = { ')': '(', ']': '[', '}': '{' };

  for (const ch of s) {
    if (ch === '(' || ch === '[' || ch === '{') {
      stack.push(ch);
    } else {
      if (stack.pop() !== pairs[ch]) return false;
    }
  }

  return stack.length === 0;
}

class MinStack {
  constructor() {
    this.stack = []; // entries: [value, minSoFar]
  }

  push(val) {
    const minSoFar = this.stack.length === 0
      ? val
      : Math.min(val, this.stack[this.stack.length - 1][1]);
    this.stack.push([val, minSoFar]);
  }

  pop() {
    this.stack.pop();
  }

  top() {
    return this.stack[this.stack.length - 1][0];
  }

  getMin() {
    return this.stack[this.stack.length - 1][1];
  }
}

