function minStackJudge(ops, argsList) {
  const results = [];
  let obj = null;
  for (let i = 0; i < ops.length; i++) {
    const op = ops[i];
    const opArgs = argsList[i];
    if (op === "MinStack") {
      obj = new MinStack();
      results.push(null);
    } else if (op === "push") {
      obj.push(opArgs[0]);
      results.push(null);
    } else if (op === "pop") {
      obj.pop();
      results.push(null);
    } else if (op === "top") {
      results.push(obj.top());
    } else if (op === "getMin") {
      results.push(obj.getMin());
    }
  }
  return results;
}

